"""Render docs/reference/areas.md and docs/reference/areas/<File>.md.

Output is deterministic (load order / file order, no timestamps) so that
re-running it on unchanged area files produces no diff.
"""

from __future__ import annotations

import statistics
from collections import Counter
from pathlib import Path

from ..areafile import flags as F
from ..areafile.model import Mob, Obj
from ..areafile.world import Area, World

GENERATED_NOTE = (
    "<!-- GENERATED by `python -m xania_utils docs` from xania/area. Do not edit by hand. -->\n"
)


def md(text: object) -> str:
    """Make a value safe for a Markdown table cell. Xania colour codes use
    ``|``, which would otherwise split the cell."""
    s = str(text).replace("\n", " ").strip()
    return s.replace("\\", "\\\\").replace("|", "\\|")


def table(headers: list[str], rows: list[list[object]]) -> str:
    out = ["| " + " | ".join(headers) + " |", "|" + "---|" * len(headers)]
    out += ["| " + " | ".join(md(c) for c in row) + " |" for row in rows]
    return "\n".join(out) + "\n"


def page_name(area: Area) -> str:
    return Path(area.filename).stem + ".md"


def level_band(area: Area) -> str:
    h = area.file.header
    return "all" if h.all_levels else f"{h.min_level}–{h.max_level}"


def mob_levels(area: Area) -> tuple[str, str, str]:
    levels = [m.level for m in area.file.mobs]
    if not levels:
        return "", "", ""
    return str(min(levels)), f"{statistics.median(levels):g}", str(max(levels))


# -- index page -------------------------------------------------------------
def render_index(world: World) -> str:
    rows = []
    for a in world.areas:
        f = a.file
        lo, med, hi = mob_levels(a)
        rows.append([
            a.index, f"[{a.name}](areas/{page_name(a)})", a.filename, level_band(a),
            f"{a.lowest_vnum}–{a.highest_vnum}", len(f.rooms), len(f.mobs), len(f.objects),
            len(f.resets), len(f.shops), len(f.specials), len(f.mobprogs), lo, med, hi, len(a.linked_areas),
        ])
    totals = (f"{len(world.areas)} areas, {len(world.rooms)} rooms, {len(world.mobs)} mobs, "
              f"{len(world.objects)} objects, "
              f"{sum(len(f.resets) for f in world.files)} resets, "
              f"{sum(len(f.helps) for f in world.files)} help entries, "
              f"{sum(len(f.socials) for f in world.files)} socials.")

    help_files = [f for f in world.files if not f.header]
    out = [GENERATED_NOTE, "\n# Area catalogue\n\n",
           f"Loaded from `area.lst` in boot order: {totals}\n\n",
           "Level band comes from the `{min max}` prefix of the area description (`all` if absent). "
           "Vnum range is the *effective* range after mobs/objects extend it (`Area::define_vnum`). "
           "Mob levels are min / median / max of mob prototypes in the file.\n\n",
           table(["#", "Area", "File", "Levels", "Vnums", "Rooms", "Mobs", "Objs", "Resets", "Shops",
                  "Specials", "Progs", "Mob lvl min", "med", "max", "Links"], rows)]
    if help_files:
        out.append("\n## Files without an #AREA header\n\n")
        out.append(table(["File", "Sections", "Helps", "Socials"],
                         [[f.filename, " ".join(f.sections), len(f.helps), len(f.socials)] for f in help_files]))
    out.append("\n## Load integrity\n\n")
    if world.unlisted_files:
        out.append("Area files on disk but **not in `area.lst`** (never loaded by the MUD):\n\n")
        out += [f"- `{n}`\n" for n in world.unlisted_files]
        out.append("\n")
    if world.problems:
        out.append(table(["Kind", "Where", "Message", "Fatal in C++"],
                         [[p.kind, f"{p.file}:{p.line}" if p.line else p.file, p.message,
                           "yes" if p.fatal_in_cpp else ""] for p in world.problems]))
    else:
        out.append("No cross-reference problems found. Checked: duplicate vnums; dangling exits, resets, shops, "
                   "specials and mobprogs; asymmetric two-way exits; door resets on non-doors; G/E drop rates "
                   "outside 1–100; bad wear locations; resets outside the area's vnum range.\n")
    if world.diagnostics:
        out.append("\nLoader warnings (`logger.bug` equivalents):\n\n")
        out += [f"- {d}\n" for d in world.diagnostics]
    return "".join(out)


# -- per-area page ----------------------------------------------------------
def _mob_row(m: Mob) -> list[object]:
    return [m.vnum, m.short_descr, m.level, f"{m.hit} ({m.hit.average:g})", f"{m.damage} ({m.damage.average:g})",
            m.hitroll, "/".join(map(str, m.ac)), m.attack, m.alignment, m.race,
            " ".join(m.act_names), " ".join(m.off_names)]


def _obj_values(o: Obj) -> str:
    t = o.type_name
    v = o.values
    if t == "Weapon":
        flags = " ".join(F.decode(int(v[4]), F.WEAPON_FLAG))
        avg = (int(v[1]) * int(v[2]) + int(v[1])) / 2
        return f"{v[0]} {v[1]}d{v[2]} (avg {avg:g}) {v[3]} {flags}".strip()
    if t == "Armor":
        return "AC " + "/".join(str(x) for x in v[:4])
    if t in ("Potion", "Pill", "Scroll", "Bomb"):
        spells = [str(x) for x in v[1:] if x not in (0, -1, "")]
        return f"spell lvl {v[0]}: " + ", ".join(spells)
    if t in ("Wand", "Staff"):
        return f"spell lvl {v[0]}, charges {v[2]}/{v[1]}: {v[3]}"
    if t == "Container":
        return f"capacity {v[0]}, key {v[2]}"
    if t in ("Drink", "Fountain"):
        return f"{v[1]}/{v[0]} of {v[2]}"
    return " ".join(str(x) for x in v)


def _obj_row(o: Obj) -> list[object]:
    wear = " ".join(w for w in F.decode(o.wear_flags, F.WEAR) if w != "Take")
    affects = ", ".join(f"{a.location_name} {a.modifier:+d}" for a in o.affects)
    return [o.vnum, o.short_descr, o.type_name, o.level, _obj_values(o), affects, wear,
            " ".join(F.decode(o.extra_flags, F.OBJ_EXTRA)), o.weight, o.cost]


def render_area(world: World, a: Area) -> str:
    f = a.file
    h = f.header
    out = [GENERATED_NOTE, f"\n# {a.name}\n\n",
           f"- File: `{a.filename}` (load order #{a.index})\n",
           f"- Description: `{h.description}`\n",
           f"- Level band: {level_band(a)}\n",
           f"- Declared vnums: {h.lowest_vnum}–{h.highest_vnum}; effective: {a.lowest_vnum}–{a.highest_vnum}\n",
           f"- Sections: {' '.join(f.sections)}\n",
           f"- Rooms {len(f.rooms)}, mobs {len(f.mobs)}, objects {len(f.objects)}, resets {len(f.resets)}\n"]
    if a.linked_areas:
        links = ", ".join(sorted(a.linked_areas))
        out.append(f"- Exits lead to: {links}\n")

    if f.rooms:
        sectors = Counter(r.sector_name for r in f.rooms)
        out.append("- Sectors: " + ", ".join(f"{k} {v}" for k, v in sorted(sectors.items())) + "\n")
        exits = [e for r in f.rooms for e in r.exits.values()]
        out.append(f"- Exits: {len(exits)} ({sum(e.is_door for e in exits)} doors, "
                   f"{sum(e.one_way for e in exits)} one-way, {sum(e.cosmetic for e in exits)} cosmetic)\n")
    if f.resets:
        rc = Counter(r.command for r in f.resets)
        out.append("- Resets by command: " + ", ".join(f"{k} {v}" for k, v in sorted(rc.items())) + "\n")

    if f.mobs:
        out.append("\n## Mobs\n\nHP/damage shown as dice (average). AC is pierce/bash/slash/exotic "
                   "(more negative = better). Flags are as written in the file, before race flags are merged.\n\n")
        out.append(table(["Vnum", "Name", "Lvl", "HP", "Damage", "Hitroll", "AC", "Attack", "Align", "Race",
                          "Act", "Offensive"], [_mob_row(m) for m in f.mobs]))
    if f.objects:
        out.append("\n## Objects\n\n")
        out.append(table(["Vnum", "Name", "Type", "Lvl", "Values", "Affects", "Wear", "Extra", "Wt", "Cost"],
                         [_obj_row(o) for o in f.objects]))
    if f.shops:
        out.append("\n## Shops\n\n")
        out.append(table(["Keeper", "Buys", "Profit buy %", "Profit sell %", "Hours"],
                         [[f"{s.keeper} {world.mobs[s.keeper].short_descr if s.keeper in world.mobs else '?'}",
                           ", ".join(F.OBJECT_TYPE_BY_NUM.get(t, str(t)) for t in s.buy_types if t),
                           s.profit_buy, s.profit_sell, f"{s.open_hour}–{s.close_hour}"] for s in f.shops]))
    if f.specials:
        out.append("\n## Specials\n\n")
        out.append(table(["Mob", "Spec function"],
                         [[f"{s.mob_vnum} {world.mobs[s.mob_vnum].short_descr if s.mob_vnum in world.mobs else '?'}",
                           s.spec_fun] for s in f.specials]))
    if f.mobprogs:
        out.append("\n## Mob programs\n\n")
        out.append(table(["Mob", "File", "Triggers"],
                         [[f"{p.mob_vnum} {world.mobs[p.mob_vnum].short_descr if p.mob_vnum in world.mobs else '?'}",
                           p.filename, ", ".join(sorted({mp.trigger for mp in world.mobprogs.get(p.filename, [])}))]
                          for p in f.mobprogs]))
    return "".join(out)


def write_catalogue(world: World, out_dir: Path) -> list[Path]:
    out_dir = Path(out_dir)
    area_dir = out_dir / "areas"
    area_dir.mkdir(parents=True, exist_ok=True)
    written = []
    index = out_dir / "areas.md"
    index.write_text(render_index(world), encoding="utf-8", newline="\n")
    written.append(index)
    expected = set()
    for a in world.areas:
        p = area_dir / page_name(a)
        p.write_text(render_area(world, a), encoding="utf-8", newline="\n")
        expected.add(p.name)
        written.append(p)
    for stale in area_dir.glob("*.md"):
        if stale.name not in expected:
            stale.unlink()
    return written
